while True:
  n = int(input())
  if n == 0:
    break
  targets = [tuple(map(int, input().split())) for _ in range(n)]
  m = int(input())
  x = y = 10
  direct = {"N":(0, 1), "S":(0,-1), "E":(1,0), "W":(-1,0)}
  for _ in range(m):
    d, i = input().split()
    dx, dy = direct[d]
    for dist in range(1, int(i) + 1):
      if (x + dist * dx, y + dist * dy) in targets:
        targets.remove((x + dist * dx, y + dist * dy))
    x += dx * int(i)
    y += dy * int(i)
  if targets:
    print("No")
  else:
    print("Yes")

